-- READ ONLY: schema metadata and code; no customer, menu, balance, secret or setting-value rows.
WITH application_schemas AS (
 SELECT nspname FROM pg_namespace
 WHERE nspname NOT LIKE 'pg_%' AND nspname NOT IN
 ('information_schema','auth','storage','extensions','graphql','graphql_public','realtime','net','vault','cron','supabase_migrations','supabase_functions','pgbouncer','pgsodium','pgsodium_masks')
)
SELECT jsonb_build_object(
 'captured_at',now(),'postgres_version',current_setting('server_version'),
 'application_schemas',(SELECT jsonb_agg(nspname ORDER BY nspname) FROM application_schemas),
 'extensions',(SELECT jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'relocatable',e.extrelocatable) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'acl',c.relacl,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY n.nspname,c.relname),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas) AND c.relkind IN ('r','p','v','m','S','f')),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'name',p.proname,'owner',pg_get_userbyid(p.proowner),'kind',p.prokind,'acl',p.proacl,'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.oid::regprocedure::text),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas) AND p.prokind IN ('f','p') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'types',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'definition_type',format_type(t.oid,NULL),'enum_labels',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)) ORDER BY n.nspname,t.typname),'[]') FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas) AND t.typtype IN ('e','d','r','m')),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'definition',pg_get_constraintdef(k.oid,true)) ORDER BY n.nspname,c.relname,k.conname),'[]') FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas)),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',c.relname,'valid',i.indisvalid,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY n.nspname,t.relname,c.relname),'[]') FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas)),
 'views',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'options',c.reloptions,'definition',pg_get_viewdef(c.oid,true)) ORDER BY n.nspname,c.relname),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas) AND c.relkind IN ('v','m')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'function_schema',fn.nspname,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY n.nspname,c.relname,t.tgname),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace fn ON fn.oid=p.pronamespace WHERE NOT t.tgisinternal AND (n.nspname IN (SELECT nspname FROM application_schemas) OR (n.nspname IN ('auth','storage') AND fn.nspname IN (SELECT nspname FROM application_schemas)))),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname),'[]') FROM pg_policies p WHERE schemaname IN (SELECT nspname FROM application_schemas) OR schemaname IN ('auth','storage')),
 'default_privileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_type',d.defaclobjtype,'acl',d.defaclacl) ORDER BY n.nspname,d.defaclobjtype),'[]') FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname IN (SELECT nspname FROM application_schemas) OR d.defaclnamespace=0),
 'publications',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.pubname,'all_tables',p.puballtables,'insert',p.pubinsert,'update',p.pubupdate,'delete',p.pubdelete,'truncate',p.pubtruncate,'tables',(SELECT jsonb_agg(to_jsonb(pt)) FROM pg_publication_tables pt WHERE pt.pubname=p.pubname)) ORDER BY p.pubname),'[]') FROM pg_publication p)
) AS inventory;
